namespace docking.widgets.table;









using docking.widgets.textfield;
using docking.widgets.textfield.integer;

public class HexBigIntegerTableCellEditor : AbstractCellEditor, TableCellEditor {
	protected IntegerTextField input;

	/* @Override */
	public BigInteger getCellEditorValue() {
		return input.getValue();
	}

	/* @Override */
	public bool isCellEditable(EventObject e) {
		// If mouse event, require double-click
		if (e is MouseEvent) {
			MouseEvent evt = (MouseEvent) e;
			return evt.getClickCount() >= 2 && base.isCellEditable(e);
		}
		return base.isCellEditable(e);
	}

	/* @Override */
	public Component getTableCellEditorComponent(JTable table, object value, bool isSelected,
			int row, int column) {
		input = new IntegerTextField();
		input.getComponent().setBorder(UIManager.getBorder("Table.focusCellHighlightBorder"));
		input.setMinValue(null);	// allow negative numbers
		input.setFormat(IntegerFormat.HEX);
		input.setAutoSwitchMode(false);
		input.setShowNumberMode(true);
		input.setHorizontalAlignment(SwingConstants.RIGHT);

		if (value != null) {
			input.setValue((BigInteger) value);
			CellEditorUtils.onOneFocus(input.getComponent(), () => input.selectAll());
		}
		input.addActionListener(e => stopCellEditing());
		return input.getComponent();
	}
}
